#include "stdafx.h"#include "ModbusTcpServerImpl.h"#include <macros/StrHelps.h>#include <Param.h>#include <Extern_Pnt.h>using namespace tinyxml2;void KModbusTcpServerImpl::OnAI_4_Config( tinyxml2::XMLElementPtr &item ){  ReadConfig( item, m_AIs, modelDouble64 );}void KModbusTcpServerImpl::OnAO_3_6_16_Config( tinyxml2::XMLElementPtr &item ){  ReadConfig( item, m_AOs, modelDouble64 );}void KModbusTcpServerImpl::OnDI_2_Config( tinyxml2::XMLElementPtr &item ){  ReadConfig( item, m_DIs, modelInt32 );}void KModbusTcpServerImpl::OnDO_1_5_15_Config( tinyxml2::XMLElementPtr &item ){  ReadConfig( item, m_DOs, modelInt32 );}void KModbusTcpServerImpl::ReadConfig( tinyxml2::XMLElementPtr &root, tConnectInfo_ &cont, EModelType modelTypePref ){  for( XMLElementPtr item = root->FirstChildElement(); item != NULL; item = item->NextSiblingElement() )  {    LPCSTR element_name = item->Name();    XMLElementPtr findOffset = item->FirstChildElement("offset");    XMLElementPtr findModel = item->FirstChildElement("model");    XMLElementPtr findType = item->FirstChildElement("type");    if( !findOffset || !findModel || !findType )      continue;    SPointInfo piIns;    LPCSTR pszMbType = findType->GetText();    if( !_stricmp(pszMbType,"Word") )    {      piIns.mbType = mbWord;      piIns.mbSize = sizeof(WORD);    }    else if( !_stricmp(pszMbType,"Int16") )    {      piIns.mbType = mbInt16;      piIns.mbSize = sizeof(short);    }    else if( !_stricmp(pszMbType,"Int32") )    {      piIns.mbType = mbInt32;      piIns.mbSize = sizeof(int);    }    else if( !_stricmp(pszMbType,"Float") )    {      piIns.mbType = mbFloat;      piIns.mbSize = sizeof(float);    }    else if( !_stricmp(pszMbType,"Double") )    {      piIns.mbType = mbDouble;      piIns.mbSize = sizeof(double);    }    else if( !_stricmp(pszMbType,"Bit") )      piIns.mbType = mbBit;    else if( !_stricmp(pszMbType,"Byte") )    {      piIns.mbType = mbByte;      piIns.mbSize = sizeof(BYTE);    }    else    {      ASSD(0);      continue;    }    LPCSTR pszMbAddress = findOffset->GetText();    if( mbBit==piIns.mbType )    {      LPCSTR pszPnt = strchr( pszMbAddress, '.' );      if( pszPnt )      {        piIns.mbAddress = atoi( pszMbAddress ) * 8;        ++pszPnt;        piIns.mbAddress += atoi( pszPnt );      }      else        piIns.mbAddress = atoi( pszMbAddress );    }    else      piIns.mbAddress = atoi( pszMbAddress );    LPCSTR pszModelAddress = findModel->GetText();    if( !pszModelAddress || !*pszModelAddress )      continue;    piIns.szModelAddress = findModel->GetText();    tConnectInfo_::_Pairib res = cont.insert( tConnectInfo_::value_type( piIns.mbAddress, piIns) );    if( !res.second )    {      OutputDebugString( "Не добавить точку \"");OutputDebugString( piIns.szModelAddress.c_str() ); OutputDebugString("\"\n");    }    SPointInfo &pi = res.first->second;    LPCSTR pszModel = findModel->GetText();    LPCSTR pszField =strchr( pszModel, '.' );    if( !pszField )      continue;    TStringTerminator st( (LPSTR)pszField );    ++pszField;    IBaseModel *pModel = IBaseModel::Find( (LPSTR)pszModel );    if( !pModel )    {      OutputDebugString( "Не нашел модель для точки \"");OutputDebugString( pi.szModelAddress.c_str() ); OutputDebugString("\"\n");      continue;    }    CParams::LockParams();    pModel->GetParams(NULL);    int K = CParams::kParams;    int nMB = 0;    for ( nMB; nMB < CParams::kParams; ++nMB )    {      CParams & P = CParams::Params[nMB];      if( 'T'!=P.Type )        continue;      if( !strcmp( P.ParamName, "Связь по MоdbusTCP") )      {        nMB += 1;        break;      }    }    for( int n = nMB; n < CParams::kParams; n++ )    {      CParams & P = CParams::Params[n];      if( 'E'==P.Type )        break;      if( strcmp( P.ParamName, pszField) )        continue;      switch( P.Type )      {      case 'B':        pi.modelType = modelByte;        pi.pByte = (BYTE*)P.Addr;        break;      case 'D':        pi.modelType = modelDouble64;        pi.pDouble = (double*)P.Addr;        break;      case 'L':      case 'I':        pi.modelType = modelInt32;        pi.pInt = (int*)P.Addr;        break;      default:        ASSD( !"Неизвестный тип" );        break;      }      break;    }    CParams::FreeParams();    if( modelEmpty!=pi.modelType )      continue;    CExtern_Pnt *p = pModel->GetPoint( pszField );    if( !p )    {      OutputDebugString( "Не нашел поле для точки \"");OutputDebugString( pi.szModelAddress.c_str() ); OutputDebugString("\"\n");      continue;    }    KKK();  }}